package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {









    @Test
    public void testParseOctal_SingleZeroByte() {
        byte[] buffer = {0};
        // Note: The code requires length >= 2 based on the first check
        // But if buffer[start] == 0, it returns 0L immediately.
        // However, the length check happens first.
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Should have thrown IllegalArgumentException due to length < 2");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("must be at least 2"));
        }
    }














}

