package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {





















    @Test
    public void testParseOctal_BoundaryValues() {
        // Max long for octal (approx 16 digits of '7')
        byte[] buffer = "7777777777777777".getBytes();
        long expected = 0;
        for (int i = 0; i < 16; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }


}

